fn cancel_acp_question(&mut self) {
    let Some(question) = self.acp_question.take() else {
        return;
    };
    match self.acp.cancel_session(&question.acp_session_id) {
        Ok(()) => self.status = Some("Stopped the ACP answer.".to_owned()),
        Err(error) => {
            self.status = Some(format!("Could not stop ACP answer cleanly: {error}"));
        }
    }
}

